// In-memory job state: job_id -> status ('running' | 'cancelled')
const jobs = new Map();

export async function listTools() {
  return [
    {
      name: 'start_job',
      description: 'Start a job by id. Returns a running status. Rejects duplicate active jobs.',
      inputSchema: {
        type: 'object',
        properties: {
          job_id: { type: 'string', description: 'Unique identifier for the job.' }
        },
        required: ['job_id'],
        additionalProperties: false
      }
    },
    {
      name: 'cancel_job',
      description: 'Cancel an active job by id, changing its status to cancelled. Rejects missing jobs or jobs already cancelled.',
      inputSchema: {
        type: 'object',
        properties: {
          job_id: { type: 'string', description: 'Unique identifier for the job to cancel.' }
        },
        required: ['job_id'],
        additionalProperties: false
      }
    }
  ];
}

function requireString(args, key) {
  const v = args[key];
  if (typeof v !== 'string' || v.length === 0) {
    throw new Error(`'${key}' is required and must be a non-empty string`);
  }
}

export async function callTool(name, args = {}) {
  switch (name) {
    case 'start_job': {
      requireString(args, 'job_id');
      const id = args.job_id;
      if (jobs.get(id) === 'running') {
        throw new Error(`job '${id}' is already running`);
      }
      jobs.set(id, 'running');
      return { content: [{ type: 'text', text: `job '${id}' is running` }] };
    }
    case 'cancel_job': {
      requireString(args, 'job_id');
      const id = args.job_id;
      if (!jobs.has(id)) {
        throw new Error(`job '${id}' not found`);
      }
      if (jobs.get(id) === 'cancelled') {
        throw new Error(`job '${id}' is already cancelled`);
      }
      jobs.set(id, 'cancelled');
      return { content: [{ type: 'text', text: `job '${id}' cancelled` }] };
    }
    default:
      throw new Error(`unknown tool: ${name}`);
  }
}
```

